const formatPageRange = (
  startPage: number | undefined,
  endPage: number | undefined
): string | null => {
  if (!Number.isInteger(startPage) || !Number.isInteger(endPage)) {
    return null;
  }

  return startPage === endPage ? `pag. ${startPage}` : `pag. ${startPage}-${endPage}`;
};

